package ch.emed.converter.chmed23a.validation;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Code tables of terminology.md of the pinned CHMED23A specification (research R7), vendored as
 * {@code chmed23a/terminology/*.csv} (generated by {@code tools/chmed23a/extract_fixtures.py}).
 * Immutable; loaded once.
 */
public final class Terminology {

  private static final Map<String, String[]> UNITS = load("unit.csv", true);
  private static final Map<String, String[]> ROUTES = load("route.csv", false);
  private static final Map<String, String[]> METHODS = load("method.csv", false);
  private static final Map<String, String[]> RISKS = load("risk.csv", false);

  private Terminology() {}

  /** True if the unit is a code of CDTYP 9, compared case-insensitively. */
  public static boolean isUnit(String code) {
    return code != null && UNITS.containsKey(code.toUpperCase(Locale.ROOT));
  }

  /** The code of CDTYP 9 as written in terminology.md, e.g. {@code Stk} for {@code STK}. */
  public static String unitCode(String code) {
    String[] row = code == null ? null : UNITS.get(code.toUpperCase(Locale.ROOT));
    return row == null ? null : row[0];
  }

  /** True if the code is a route of administration of CDTYP 61. */
  public static boolean isRoute(String code) {
    return code != null && ROUTES.containsKey(code);
  }

  /** True if the code is a method of administration of CDTYP 62. */
  public static boolean isMethod(String code) {
    return code != null && METHODS.containsKey(code);
  }

  /** German display of a method of administration, or null. */
  public static String methodGerman(String code) {
    String[] row = code == null ? null : METHODS.get(code);
    return row == null ? null : row[1];
  }

  /**
   * The risk category of a risk id (README "RiskCategory"; allergies are category 6).
   *
   * @return the category, or null if the risk id is unknown
   */
  public static Integer riskCategory(Integer riskId) {
    String[] row = riskId == null ? null : RISKS.get(riskId.toString());
    return row == null ? null : Integer.valueOf(row[1]);
  }

  /** Number of codes per table, for the test against terminology.md. */
  static Map<String, Integer> sizes() {
    return Map.of(
        "unit", UNITS.size(),
        "route", ROUTES.size(),
        "method", METHODS.size(),
        "risk", RISKS.size());
  }

  private static Map<String, String[]> load(String name, boolean upperCaseKeys) {
    String resource = "/chmed23a/terminology/" + name;
    Map<String, String[]> rows = new LinkedHashMap<>();
    try (InputStream in = Terminology.class.getResourceAsStream(resource)) {
      if (in == null) {
        throw new IllegalStateException("Missing resource " + resource);
      }
      BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
      boolean header = true;
      for (String line = reader.readLine(); line != null; line = reader.readLine()) {
        if (line.startsWith("#") || line.isBlank()) {
          continue;
        }
        if (header) {
          header = false;
          continue;
        }
        String[] row = line.split(";", -1);
        rows.putIfAbsent(upperCaseKeys ? row[0].toUpperCase(Locale.ROOT) : row[0], row);
      }
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
    return Map.copyOf(rows);
  }
}
